package com.yuegang.zhihui.order.application;import com.yuegang.zhihui.inventory.api.InventoryCommand;import com.yuegang.zhihui.order.api.*;import com.yuegang.zhihui.order.infrastructure.InventoryClient;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;public final class OrderInventoryFacade{private final OrderService orders;private final InventoryClient inventory;private final JdbcTemplate jdbc;public OrderInventoryFacade(OrderService o,InventoryClient i,DataSource d){orders=o;inventory=i;jdbc=new JdbcTemplate(d);}public OrderView create(long user,CreateOrderRequest request){List<InventoryCommand>reserved=new ArrayList<>();try{for(var item:request.items()){var c=command(request.requestId(),item.skuId(),item.quantity());inventory.reserve(c);reserved.add(c);}return orders.create(user,request);}catch(RuntimeException failure){for(var c:reserved)try{inventory.release(c);}catch(RuntimeException ignored){}throw failure;}}public OrderView cancel(long user,String order,long version){OrderView result=orders.cancel(user,order,version);for(var c:commands(order))inventory.release(c);return result;}public int closeExpired(){List<String>ids=jdbc.queryForList("SELECT CAST(id AS CHAR) FROM order_main WHERE status='PENDING_PAYMENT' AND expires_at<NOW(6)",String.class);int closed=orders.closeExpired();for(String id:ids)for(var c:commands(id))try{inventory.release(c);}catch(RuntimeException ignored){}return closed;}public void paymentSucceeded(String eventId,String order){orders.paymentSucceeded(eventId,order);for(var c:commands(order))inventory.confirm(c);}public void refundSucceeded(String eventId,String order){orders.refundSucceeded(eventId,order);}private List<InventoryCommand>commands(String order){return jdbc.query("SELECT m.request_id,i.sku_id,i.quantity FROM order_main m JOIN order_item i ON i.order_id=m.id WHERE m.id=?",(r,n)->command(r.getString(1),Long.toString(r.getLong(2)),r.getLong(3)),Long.parseLong(order));}private static InventoryCommand command(String request,String sku,long quantity){String key=request+":"+sku;if(key.length()>128)key=hex(key);return new InventoryCommand(key,sku,quantity,"ORDER",request);}private static String hex(String value){try{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}
